#!/usr/bin/env python3
"""Applies Bodiana settings to the Android project generated by `flutter create`.

Run from the project root after:
    flutter create --org com.bodiana --project-name bodiana --platforms android .

- application id  -> com.bodiana.app
- app name        -> Bodiana
- INTERNET permission (release builds need it explicitly)
- deep link com.bodiana.app://login-callback (Google sign-in, email links)
- intent queries for phone / WhatsApp / maps links
- launcher icons from branding/android
"""
import pathlib
import re
import shutil
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
APP_ID = "com.bodiana.app"
android = ROOT / "android"
if not android.exists():
    sys.exit("android/ folder not found. Run `flutter create --platforms android .` first.")

# 1. Application id (Groovy or Kotlin DSL)
gradle_files = [android / "app" / "build.gradle.kts", android / "app" / "build.gradle"]
patched = False
for f in gradle_files:
    if f.exists():
        text = f.read_text()
        new = re.sub(r'applicationId\s*=\s*"[^"]+"', f'applicationId = "{APP_ID}"', text)
        new = re.sub(r'applicationId\s+"[^"]+"', f'applicationId "{APP_ID}"', new)
        f.write_text(new)
        patched = patched or (new != text) or (APP_ID in new)
if not patched:
    sys.exit("Could not find applicationId in android/app/build.gradle(.kts)")

# 2. Manifest
manifest = android / "app" / "src" / "main" / "AndroidManifest.xml"
m = manifest.read_text()

if "android.permission.INTERNET" not in m:
    m = m.replace(
        '<application',
        '<uses-permission android:name="android.permission.INTERNET" />\n    <application',
        1,
    )

m = re.sub(r'android:label="[^"]*"', 'android:label="Bodiana"', m, count=1)

deep_link = """
            <!-- Supabase auth deep link (Google sign-in, email confirmation, password reset) -->
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="com.bodiana.app" android:host="login-callback" />
            </intent-filter>
        </activity>"""
if "login-callback" not in m:
    m = m.replace("</activity>", deep_link.lstrip("\n"), 1)

queries = """
    <queries>
        <intent>
            <action android:name="android.intent.action.VIEW" />
            <data android:scheme="https" />
        </intent>
        <intent>
            <action android:name="android.intent.action.DIAL" />
            <data android:scheme="tel" />
        </intent>
    </queries>
</manifest>"""
if 'android:scheme="tel"' not in m:
    idx = m.rfind("</manifest>")
    m = m[:idx] + queries.lstrip("\n") + m[idx + len("</manifest>"):]

manifest.write_text(m)

# 3. Launcher icons
res = android / "app" / "src" / "main" / "res"
for folder in (ROOT / "branding" / "android").glob("mipmap-*"):
    target = res / folder.name
    target.mkdir(parents=True, exist_ok=True)
    shutil.copy(folder / "ic_launcher.png", target / "ic_launcher.png")

print("Android project patched:", APP_ID)
print(m)
